package app

import app.repositories.CountryRepository
import app.repositories.CustomerRepository
import app.repositories.OrderRepository
import app.repositories.ProductRepository
import app.repositories.MongoCountryRepository
import app.repositories.MongoCustomerRepository
import app.repositories.MongoOrderRepository
import app.repositories.MongoProductRepository

/** The repositories over one Db, and its transaction. */
class MongoUnitOfWork(val db: Db) : UnitOfWork {
    override val customers: CustomerRepository = MongoCustomerRepository(db)
    override val products: ProductRepository = MongoProductRepository(db)
    override val orders: OrderRepository = MongoOrderRepository(db)
    override val countries: CountryRepository = MongoCountryRepository(db)

    /** Joins the transaction already open, or opens one. */
    override fun <T> transaction(work: (UnitOfWork) -> T): T {
        // Joins the transaction already open
        if (db.inTransaction) return work(this)
        db.begin()
        try {
            val result = work(this)
            db.commit()
            return result
        } catch (error: Throwable) {
            db.rollback()
            throw error
        }
    }
}

