import app.common.Page
import app.entities.Country

/** Keeps countries rows in memory, for tests and for trying the services without a database. */
class MemoryCountryRepository : CountryRepository {
    private val rows = linkedMapOf<List<Any?>, Country>()

    /** The key of a row, as a list of its key values. */
    private fun keyOf(row: Country): List<Any?> = listOf(row.documentId)

    /** Orders two keys value by value. */
    @Suppress("UNCHECKED_CAST")
    private fun compareKeys(a: List<Any?>, b: List<Any?>): Int {
        for (index in a.indices) {
            val order = compareValues(a[index] as Comparable<Any>?, b[index] as Comparable<Any>?)
            if (order != 0) return order
        }
        return 0
    }

    private fun visible(): List<Country> =
        rows.values.filter { true }.sortedWith { a, b -> compareKeys(keyOf(a), keyOf(b)) }

    override fun findByDocumentId(documentId: String): Country? {
        return visible().firstOrNull { it.documentId == documentId }
    }

    override fun list(offset: Int, limit: Int): Page<Country> {
        val rows = visible()
        return Page(rows.drop(offset).take(limit), rows.size.toLong(), offset, limit)
    }

    override fun findById(id: Double): Country? {
        return visible().firstOrNull { it.id == id }
    }

    override fun insert(entity: Country): Country {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun update(entity: Country): Country {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun delete(entity: Country): Unit {
        rows.remove(keyOf(entity))
    }
}

