package app.repositories

import app.Db
import app.Documents
import app.common.Page
import app.entities.Country
import java.util.Collections
import java.util.WeakHashMap
import org.bson.Document

/** Keeps countries rows in the database, through the MongoDB driver. It runs in the transaction already open, when there is one. */
class MongoCountryRepository(private val db: Db) : CountryRepository {
    private val collection = "countries"

    /** The fields a change may write */
    private val fields = listOf("id", "name")

    override fun findByDocumentId(documentId: String): Country? {
        return db.find(collection, Document("_id", documentId), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Country> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun findById(id: Double): Country? {
        return db.find(collection, Document("id", id), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun insert(entity: Country): Country {
        db.insert("Country", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Country): Country {
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("Country", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Country): Unit {
        db.delete("Country", collection, Document("_id", entity.documentId!!))
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Country {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Country: what is null is left out. */
    private fun toDocument(value: Country): Document {
        val document = Document()
        value.documentId?.let { document["_id"] = it }
        value.id?.let { document["id"] = it }
        value.name?.let { document["name"] = it }
        return document
    }

    private fun fromDocument(document: Document): Country =
        Country(
            documentId = document["_id"] as String?,
            id = (document["id"] as Number?)?.toDouble(),
            name = document["name"] as String?,
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<Country, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

