package app.repositories

import app.Db
import app.Documents
import app.common.Page
import app.entities.Order
import java.time.Instant
import java.util.Collections
import java.util.Date
import java.util.WeakHashMap
import org.bson.Document
import org.bson.types.Decimal128
import org.bson.types.ObjectId

/** Keeps orders rows in the database, through the MongoDB driver. It runs in the transaction already open, when there is one. */
class MongoOrderRepository(private val db: Db) : OrderRepository {
    private val collection = "orders"

    /** The fields a change may write */
    private val fields = listOf("number", "year", "customer", "lines", "notes")

    override fun findById(id: String): Order? {
        if (!ObjectId.isValid(id)) return null
        return db.find(collection, Document("_id", ObjectId(id)), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Order> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun findByYearAndNumber(year: Double, number: Double): Order? {
        return db.find(collection, Document("year", year).append("number", number), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun listByCustomer(customer: String): List<Order> {
        if (!ObjectId.isValid(customer)) return emptyList()
        return db.find(collection, Document("customer", ObjectId(customer)), sort = Document("_id", 1)).map { loaded(it) }
    }

    override fun insert(entity: Order): Order {
        entity.id = entity.id ?: ObjectId().toHexString()
        entity.placedAt = entity.placedAt ?: Instant.now()
        entity.identifyItems()
        db.insert("Order", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Order): Order {
        entity.identifyItems()
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("Order", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Order): Unit {
        db.delete("Order", collection, Document("_id", ObjectId(entity.id!!)))
    }

    override fun addLine(id: String, line: Order.Line): Order? {
        if (!ObjectId.isValid(id)) return null
        line.id = line.id ?: ObjectId().toHexString()
        val change = Document("\$push", Document("lines", lineToDocument(line)))
        return db.change("Order", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    override fun removeLine(id: String, lineId: String): Order? {
        if (!ObjectId.isValid(id)) return null
        if (!ObjectId.isValid(lineId)) return null
        val change = Document("\$pull", Document("lines", Document("_id", ObjectId(lineId))))
        return db.change("Order", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    override fun addNote(id: String, note: Order.Note): Order? {
        if (!ObjectId.isValid(id)) return null
        note.id = note.id ?: ObjectId().toHexString()
        val change = Document("\$push", Document("notes", noteToDocument(note)))
        return db.change("Order", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    override fun removeNote(id: String, noteId: String): Order? {
        if (!ObjectId.isValid(id)) return null
        if (!ObjectId.isValid(noteId)) return null
        val change = Document("\$pull", Document("notes", Document("_id", ObjectId(noteId))))
        return db.change("Order", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Order {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Order: what is null is left out. */
    private fun toDocument(value: Order): Document {
        val document = Document()
        value.id?.let { document["_id"] = ObjectId(it) }
        value.number?.let { document["number"] = it }
        value.year?.let { document["year"] = it }
        value.customer?.let { document["customer"] = ObjectId(it) }
        value.lines?.let { held -> document["lines"] = held.map { lineToDocument(it) } }
        value.notes?.let { held -> document["notes"] = held.map { noteToDocument(it) } }
        value.placedAt?.let { document["placedAt"] = Date.from(it) }
        return document
    }

    private fun fromDocument(document: Document): Order =
        Order(
            id = document["_id"]?.toString(),
            number = (document["number"] as Number?)?.toDouble(),
            year = (document["year"] as Number?)?.toDouble(),
            customer = document["customer"]?.toString(),
            lines = (document["lines"] as List<*>?)?.mapNotNull { (it as Document?)?.let { lineFromDocument(it) } },
            notes = (document["notes"] as List<*>?)?.mapNotNull { (it as Document?)?.let { noteFromDocument(it) } },
            placedAt = (document["placedAt"] as Date?)?.toInstant(),
        )

    /** The document of a Order.Line: what is null is left out. */
    private fun lineToDocument(value: Order.Line): Document {
        val document = Document()
        value.id?.let { document["_id"] = ObjectId(it) }
        value.product?.let { document["product"] = ObjectId(it) }
        value.quantity?.let { document["quantity"] = it }
        value.price?.let { document["price"] = Decimal128(it) }
        value.status?.let { document["status"] = it }
        return document
    }

    private fun lineFromDocument(document: Document): Order.Line =
        Order.Line(
            id = document["_id"]?.toString(),
            product = document["product"]?.toString(),
            quantity = (document["quantity"] as Number?)?.toDouble(),
            price = Documents.decimal(document["price"]),
            status = document["status"] as String?,
        )

    /** The document of a Order.Note: what is null is left out. */
    private fun noteToDocument(value: Order.Note): Document {
        val document = Document()
        value.id?.let { document["_id"] = ObjectId(it) }
        value.text?.let { document["text"] = it }
        value.at?.let { document["at"] = Date.from(it) }
        return document
    }

    private fun noteFromDocument(document: Document): Order.Note =
        Order.Note(
            id = document["_id"]?.toString(),
            text = document["text"] as String?,
            at = (document["at"] as Date?)?.toInstant(),
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<Order, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

