package app.services

import app.UnitOfWork
import app.common.Page
import app.entities.Country
import app.errors.ConflictException
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException

/** Operations on countries. Each write runs in its own transaction. */
class CountryService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Country after checking it. */
    fun createCountry(country: Country): Country {
        val values = mapOf(
            "documentId" to country.documentId,
            "id" to country.id,
            "name" to country.name,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            uow.countries.insert(country)
        }
    }

    /** The Country with this key; NotFoundException when there is none. */
    fun getCountry(documentId: String): Country = find(unitOfWork, documentId)

    /** A page of countries, by primary key. */
    fun listCountries(offset: Int, limit: Int): Page<Country> = unitOfWork.countries.list(offset, limit)

    /** Changes the given values of a Country. */
    fun updateCountry(documentId: String, changes: CountryChanges): Country {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, documentId)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.countries.update(current)
        }
    }

    /** Deletes a Country. */
    fun deleteCountry(documentId: String) {
        unitOfWork.transaction { uow ->
            val current = find(uow, documentId)
            uow.countries.delete(current)
        }
    }

    /** The Country with this id, or null. */
    fun findCountryById(id: Double): Country? = unitOfWork.countries.findById(id)

    /** Checks the values against the rules of the "countries" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Country?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["documentId"]
            if (value == null) {
                if (creating || "documentId" in values) errors += FieldError("_id", "is required")
            }
        }
        run {
            val value = values["id"]
            if (value == null) {
                if (creating || "id" in values) errors += FieldError("id", "is required")
            }
        }
        run {
            val value = values["name"]
            if (value == null) {
                if (creating || "name" in values) errors += FieldError("name", "is required")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Country", errors)
    }

    /** Values that must be unique are not taken by another row. */
    private fun checkUnique(uow: UnitOfWork, values: Map<String, Any?>, current: Country?) {
        run {
            val id = if ("id" in values) values["id"] as Double? else current?.id
            if (id != null) {
                val other = uow.countries.findById(id)
                if (other != null && (current == null || other.documentId != current.documentId))
                    throw ConflictException("Country", "id is already taken", listOf("id"))
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Country?) {
        validate(uow, values, current)
        checkUnique(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Country, values: Map<String, Any?>) {
        if ("documentId" in values) entity.documentId = values["documentId"] as String?
        if ("id" in values) entity.id = values["id"] as Double?
        if ("name" in values) entity.name = values["name"] as String?
    }

    /** The Country with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, documentId: String): Country =
        uow.countries.findByDocumentId(documentId) ?: throw NotFoundException("Country", documentId)

    /** The values an update gives, by field. */
    private fun given(changes: CountryChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.id.isPresent) values["id"] = changes.id.value
        if (changes.name.isPresent) values["name"] = changes.name.value
        return values
    }
}

