            }
        }
    }

    /** What a Customer.Preferences does not follow of its rules, each with the path of its field. */
    @Suppress("UNUSED_PARAMETER")
    private fun checkPreferences(value: Customer.Preferences, path: String, errors: MutableList<FieldError>) {
    }
