        val errors = mutableListOf<FieldError>()
        run {
            val value = values["number"]
            if (value == null) {
                if (creating || "number" in values) errors += FieldError("number", "is required")
            }
        }
        run {
            val value = values["year"]
            if (value == null) {
                if (creating || "year" in values) errors += FieldError("year", "is required")
            }
        }
        run {
            val value = values["customer"]
            if (value == null) {
                if (creating || "customer" in values) errors += FieldError("customer", "is required")
            }
        }
        run {
            val value = values["lines"]
            if (value == null) {
                if (creating || "lines" in values) errors += FieldError("lines", "is required")
            } else {
                val document = value as List<Order.Line>
                document.forEachIndexed { i0, item0 ->
                    checkLine(item0, "lines" + "." + i0, errors)
                }
            }
        }
        run {
            val value = values["notes"]
            if (value != null) {
                val document = value as List<Order.Note>
                document.forEachIndexed { i0, item0 ->
                    checkNote(item0, "notes" + "." + i0, errors)
                }
            }
        }
        run {
            val customer = if ("customer" in values) values["customer"] as String? else current?.customer
            if (customer != null && uow.customers.findById(customer) == null)
                errors += FieldError("customer", "no Customer has this key")
