            val number = if ("number" in values) values["number"] as Double? else current?.number
            if (year != null && number != null) {
                val other = uow.orders.findByYearAndNumber(year, number)
                if (other != null && (current == null || other.id != current.id))
                    throw ConflictException("Order", "year, number is already taken", listOf("year", "number"))
            }
        }
    }

