    private fun applyValues(entity: Order, values: Map<String, Any?>) {
        if ("number" in values) entity.number = values["number"] as Double?
        if ("year" in values) entity.year = values["year"] as Double?
        if ("customer" in values) entity.customer = values["customer"] as String?
        if ("lines" in values) entity.lines = values["lines"] as List<Order.Line>?
        if ("notes" in values) entity.notes = values["notes"] as List<Order.Note>?
    }

