    private fun given(changes: OrderChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.number.isPresent) values["number"] = changes.number.value
        if (changes.year.isPresent) values["year"] = changes.year.value
        if (changes.customer.isPresent) values["customer"] = changes.customer.value
        if (changes.lines.isPresent) values["lines"] = changes.lines.value
        if (changes.notes.isPresent) values["notes"] = changes.notes.value
        return values
    }

    /** What a Order.Line does not follow of its rules, each with the path of its field. */
    private fun checkLine(value: Order.Line, path: String, errors: MutableList<FieldError>) {
        if (value.product == null) errors += FieldError(path + ".product", "is required")
        value.quantity.let { held ->
            if (held == null) errors += FieldError(path + ".quantity", "is required")
            else {
