            }
        }
        if (value.price == null) errors += FieldError(path + ".price", "is required")
        value.status.let { held ->
            if (held != null) {
                if (held !in listOf("pending", "sent")) errors += FieldError(path + ".status", "must be one of: pending, sent")
            }
        }
    }

