package app

import com.mongodb.client.model.IndexOptions
import org.bson.Document

/** The test database: the MongoDB database TEST_DATABASE_URL names, with every collection created empty before every test. */
object TestDatabase {
    val url: String by lazy {
        checkNotNull(System.getenv("TEST_DATABASE_URL")) {
            "The database tests need a disposable MongoDB database (a replica set, for its transactions): set TEST_DATABASE_URL (it is emptied)"
        }
    }

    val client by lazy { AppDatabase.client(url) }

    /** The repositories over the test database, with its collections and their indexes created again. */
    fun open(): MongoUnitOfWork {
        val db = Db(client, AppDatabase.name(url))
        db.database.drop()
        db.database.createCollection("customers")
        db.database.createCollection("products")
        db.database.createCollection("orders")
        db.database.createCollection("countries")
        db.collection("customers").createIndex(Document("email", 1), IndexOptions().unique(true))
        db.collection("products").createIndex(Document("sku", 1), IndexOptions().unique(true))
        db.collection("products").createIndex(Document("title", 1))
        db.collection("orders").createIndex(Document("year", 1).append("number", 1), IndexOptions().unique(true))
        db.collection("orders").createIndex(Document("customer", 1))
        db.collection("countries").createIndex(Document("id", 1), IndexOptions().unique(true))
        return MongoUnitOfWork(db)
    }
}
